package dev.veltraph.client.farming.movement;
import dev.veltraph.client.world.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
final class CropCompletionBatchTest {
 @Test void severalMissedPlantsUseOneRestoreAtExhaustion(){var b=new CropCompletionBatch();b.start(100);for(int x=0;x<4;x++){b.visited(new BlockPos(x,71,0));assertFalse(b.restoring());assertEquals(0,b.restoreCount());}b.restore();b.finish(new Vec3(57.5,70,.5),500);assertEquals(1,b.restoreCount());assertFalse(b.active());}
 @Test void finiteBudgetAndPlantLimitPreventEndlessWindow(){var b=new CropCompletionBatch();b.start(100);assertFalse(b.expired(8099));assertTrue(b.expired(8100));b.start(100);for(int x=0;x<12;x++)b.visited(new BlockPos(x,71,0));assertTrue(b.expired(101));}
 @Test void primaryRowMustProgressBeforeNextLookBackWindow(){var b=new CropCompletionBatch();var feet=new Vec3(57.5,70,.5);b.start(0);b.restore();b.finish(feet,100);assertFalse(b.canStart(feet,2000));assertFalse(b.canStart(new Vec3(57.5,70,2.5),1099));var scope=new CropCompletionBatch.RowScope(this,this,this,this,1);for(int i=0;i<8;i++)b.observePrimary(new CropCompletionBatch.RowEvidence(scope,i,new Vec3(57.5,70,.5+i*.2),0,1,true));assertTrue(b.canStart(new Vec3(57.5,70,1.9),1100,scope));}
 @Test void clockRollbackAndCancelRevokeBatch(){var b=new CropCompletionBatch();b.start(100);assertTrue(b.expired(99));b.cancel();assertFalse(b.active());assertTrue(b.visited().isEmpty());}
 @Test void verticalOnlyAndRollbackCannotReenter(){var b=new CropCompletionBatch();var feet=new Vec3(57.5,70,.5);b.start(100);b.restore();b.finish(feet,500);var scope=new CropCompletionBatch.RowScope(this,this,this,this,1);for(int i=0;i<8;i++)b.observePrimary(new CropCompletionBatch.RowEvidence(scope,i,new Vec3(57.5,70+i,.5),0,1,true));assertFalse(b.canStart(new Vec3(57.5,77,.5),2000,scope));assertFalse(b.canStart(feet,499,scope));assertFalse(b.canStart(feet,2000,scope));}
 @Test void ForeignContextAndTeleportSizedMotionCannotQualify(){var b=new CropCompletionBatch();var feet=new Vec3(57.5,70,.5);b.start(0);b.restore();b.finish(feet,100);var scope=new CropCompletionBatch.RowScope(this,this,this,this,1);b.observePrimary(new CropCompletionBatch.RowEvidence(scope,1,feet,0,1,true));b.observePrimary(new CropCompletionBatch.RowEvidence(scope,2,new Vec3(57.5,70,4.5),0,1,true));assertFalse(b.canStart(new Vec3(57.5,70,4.5),2000,scope));for(int i=3;i<11;i++)b.observePrimary(new CropCompletionBatch.RowEvidence(scope,i,new Vec3(57.5,70,4.5+(i-2)*.2),0,1,true));assertFalse(b.canStart(new Vec3(57.5,70,6.1),2000,new CropCompletionBatch.RowScope(new Object(),this,this,this,1)));}

 @Test void horizontalDisplacementWithoutOwnedRowEvidenceNeverQualifies(){var b=new CropCompletionBatch();b.start(0);b.restore();b.finish(new Vec3(57.5,70,.5),100);assertFalse(b.canStart(new Vec3(57.5,70,4.5),2000));var scope=new CropCompletionBatch.RowScope(this,this,this,this,1);b.observePrimary(new CropCompletionBatch.RowEvidence(scope,1,new Vec3(57.5,70,.5),0,1,false));b.observePrimary(new CropCompletionBatch.RowEvidence(scope,2,new Vec3(57.5,70,.7),0,1,false));assertFalse(b.canStart(new Vec3(57.5,70,.7),2000,scope));}

}
